alter table public.units add column if not exists is_collectible boolean not null default false;
alter table public.web_orders add column if not exists tax_remitted_by text;
do $$ begin alter table public.web_orders add constraint web_orders_tax_remitted_by_check check (tax_remitted_by is null or tax_remitted_by in ('marketplace','store','none')); exception when duplicate_object then null; end $$;
alter table public.marketplace_email_sales add column if not exists fee_cents int, add column if not exists tax_cents int, add column if not exists shipping_cost_cents int, add column if not exists tax_remitted_by text;
insert into public.store_settings (store_id, key, value) select s.id, 'cost_defaults', '{"refrigerators":25000,"dishwashers":25000,"mattresses":30000,"other":900}'::jsonb from public.stores s on conflict (store_id, key) do nothing;
insert into public.store_settings (store_id, key, value) select s.id, 'ledger_payout_effective_from', '"2026-10-06T07:00:00.000Z"'::jsonb from public.stores s on conflict (store_id, key) do nothing;
insert into public.store_settings (store_id, key, value) select s.id, 'ledger_payout_rules', jsonb_build_object('paul_employee_id','f17e6163-b10a-4fe1-a373-75c0094e5363','jacob_employee_id','f0228ad1-9b30-4e6a-8df5-d237933ffc9b','online_paul_pct',30,'instore_paul_pct',20,'instore_jacob_pct',10) from public.stores s on conflict (store_id, key) do nothing;
update public.store_settings ss set value = coalesce(ss.value,'[]'::jsonb) || case when not exists (select 1 from jsonb_array_elements(ss.value) x where x->>'key'='amazon') then '[{"key":"amazon","label":"Amazon","aliases":["amazon","amazon.com"]}]'::jsonb else '[]'::jsonb end || case when not exists (select 1 from jsonb_array_elements(ss.value) x where x->>'key'='tiktok') then '[{"key":"tiktok","label":"TikTok Shop","aliases":["tiktok","tiktok shop"]}]'::jsonb else '[]'::jsonb end where ss.key='marketplace_channels';
update public.store_settings ss set value=(select jsonb_agg(to_jsonb(k) order by k) from (select distinct lower(btrim(x)) k from jsonb_array_elements_text(case when jsonb_typeof(ss.value)='array' then ss.value else '[]'::jsonb end) x union select 'amazon' union select 'tiktok') q where k is not null and k<>'') where ss.key='online_channels';